import { FormEvent, useCallback, useEffect, useMemo, useRef, useState } from 'react';
import {
  AlertTriangle,
  Building2,
  Camera,
  Check,
  Clipboard,
  DoorOpen,
  Download,
  FilePenLine,
  Globe2,
  Info,
  Phone,
  RefreshCw,
  Search,
  Settings,
  Tag,
  User,
  UserRound,
  Users,
  Wifi,
  WifiOff,
  X,
} from 'lucide-react';

import { clearGuardToken, getGuardToken, setGuardToken } from '../../api/client';
import {
  checkInVisitor,
  checkOutVisitor,
  getActiveVisitors,
  getExpectedGuests,
  getGuardSession,
  guardLogin,
  guardLogout,
  manualEntry,
  markStaffIn,
  markStaffOut,
  searchStaff,
  type ExpectedGuest,
  verifyQr,
  type StaffMember,
  type VerifyQrResponse,
  type VisitorSession,
} from '../../api/visitor';
import { getOrCreateDeviceId } from '../../lib/device';
import {
  clearGuardAuth,
  createOfflineEvent,
  enqueue,
  getPendingCount,
  loadGuardAuth,
  processQueue,
  registerBackgroundSync,
  saveGuardAuth,
} from './offlineQueue';
import { extractToken, QrScanner, type ExtractedQrToken } from './QrScanner';
import './legacyGuard.css';

type GuardScreen = 'login' | 'scanner' | 'visitors' | 'manual' | 'expected' | 'settings';
type Lang = 'hi' | 'en';
type ToastTone = 'success' | 'error' | 'info';
type InstallAppHandler = () => void;

interface BeforeInstallPromptEvent extends Event {
  readonly platforms: string[];
  readonly userChoice: Promise<{ outcome: 'accepted' | 'dismissed'; platform: string }>;
  prompt(): Promise<void>;
}

interface ToastState {
  message: string;
  tone: ToastTone;
  icon?: IconName;
}

type IconName =
  | 'alert'
  | 'building'
  | 'camera'
  | 'check'
  | 'clipboard'
  | 'door'
  | 'download'
  | 'globe'
  | 'info'
  | 'offline'
  | 'pencil'
  | 'people'
  | 'person'
  | 'phone'
  | 'refresh'
  | 'search'
  | 'settings'
  | 'tag'
  | 'wifi'
  | 'wifi-off'
  | 'x';

interface OfflineEventRecord {
  id?: number;
  offlineEventId: string;
  eventType: string;
  visitorName?: string;
  visitor_name?: string;
  phone?: string;
  purpose?: string;
  hostName?: string;
  host?: string;
  qrToken?: string;
  sessionId?: string;
  checkoutTime?: string;
}

interface VisitorMeta {
  visitorName: string | null;
  purpose: string | null;
  hostName: string | null;
  phone: string | null;
  validFrom: string | null;
  expiresAt: string | null;
}

interface CurrentVisitorCard {
  token: string;
  data?: VerifyQrResponse;
  offlinePending?: boolean;
  offlineEventId?: string;
  visitorMeta?: VisitorMeta | null;
}

const tabs: Array<{ id: Exclude<GuardScreen, 'login'>; labelKey: string; icon: IconName }> = [
  { id: 'scanner', labelKey: 'tab_scan', icon: 'camera' },
  { id: 'visitors', labelKey: 'tab_visitors', icon: 'people' },
  { id: 'manual', labelKey: 'tab_entry', icon: 'pencil' },
  { id: 'expected', labelKey: 'tab_search', icon: 'search' },
  { id: 'settings', labelKey: 'tab_settings', icon: 'settings' },
];

export function GuardApp() {
