    let cancelled = false;
    async function load() {
      try {
        const res = await fetch(`/locales/${lang}.json`, { cache: 'no-cache' });
        const data = (await res.json()) as Record<string, string>;
        if (!cancelled) setStrings(data);
      } catch {
        if (!cancelled) setStrings({});
      }
    }
    localStorage.setItem('guard_lang', lang);
    void load();
    return () => {
      cancelled = true;
    };
  }, [lang]);

