    };
  }, [booting, online]);

  useEffect(() => {
    document.body.classList.add('guard-pwa-shell');
    return () => document.body.classList.remove('guard-pwa-shell');
  }, []);

  useEffect(() => {
    const standaloneQuery = window.matchMedia?.('(display-mode: standalone)');
    const syncStandaloneState = () => {
      setRunningStandalone(isRunningStandalone());
      if (isRunningStandalone()) setInstallPrompt(null);
    };
    const onBeforeInstallPrompt = (event: Event) => {
      if (isRunningStandalone()) return;
      event.preventDefault();
      setInstallPrompt(event as BeforeInstallPromptEvent);
    };
    const onAppInstalled = () => {
      setInstallPrompt(null);
      setRunningStandalone(true);
      showToast(t('install_success'), 'success', 'check');
    };

