    const onOffline = () => {
      setOnline(false);
      showToast(t('offline_banner'), 'error', 'wifi-off');
    };
    const onOnline = () => {
      setOnline(true);
      void registerBackgroundSync();
      void attemptQueueSync({ reason: 'reconnect', announceReconnect: true });
    };
    window.addEventListener('offline', onOffline);
    window.addEventListener('online', onOnline);
    return () => {
      window.removeEventListener('offline', onOffline);
      window.removeEventListener('online', onOnline);
    };
  }, [showToast, t]);

  useEffect(() => {
    const handler = () => setUpdateReady(true);
    window.addEventListener('app-update-ready', handler);
    return () => window.removeEventListener('app-update-ready', handler);
  }, []);

  useEffect(() => {
    const onMessage = (event: MessageEvent) => {
      if (event.data?.type !== 'offline-sync-complete') return;
      setLastSyncSummary(event.data.summary ?? null);
      void refreshPendingCount();
    };
    navigator.serviceWorker?.addEventListener?.('message', onMessage);
    return () => navigator.serviceWorker?.removeEventListener?.('message', onMessage);
  }, [refreshPendingCount]);

  useEffect(() => {
    if (didRestoreSession.current) return;
    didRestoreSession.current = true;

    async function restoreSession() {
      const savedAuth = (await loadGuardAuth()) as { token?: string; guardName?: string; guardId?: string } | null;
      const savedToken = getGuardToken() || savedAuth?.token || null;
      setBootMessage(savedToken ? t('restoring_session') : t('loading'));
      await refreshPendingCount();

      if (!savedToken) {
        setScreen('login');
        setBooting(false);
        return;
      }

      setGuardToken(savedToken);
      if (savedAuth?.guardName) localStorage.setItem('guard_name', savedAuth.guardName);
      if (savedAuth?.guardId) localStorage.setItem('guard_id', savedAuth.guardId);

      if (!navigator.onLine) {
        setScreen('scanner');
        setBooting(false);
        return;
