      if (session.ok) {
        if (session.data.guardName) localStorage.setItem('guard_name', session.data.guardName);
        if (session.data.guardId) localStorage.setItem('guard_id', session.data.guardId);
        await saveGuardAuth({
          token: savedToken,
          guardId: session.data.guardId || null,
          guardName: session.data.guardName || savedAuth?.guardName || null,
        });
        if (session.data.language) setLang(session.data.language === 'hindi' ? 'hi' : 'en');
        setScreen('scanner');
        void registerBackgroundSync();
        void attemptQueueSync({ reason: 'startup', silentWhenEmpty: true, silentSummary: true });
      } else if (session.status === 401) {
        await clearSavedGuardSession();
        setScreen('login');
      } else {
        setScreen('scanner');
      }
      setBooting(false);
    }

    void restoreSession();
  }, [refreshPendingCount]);

  useEffect(() => {
    const onExpired = () => {
      void (async () => {
        await clearSavedGuardSession();
        setScreen('login');
        showToast(t('visitors_error_auth'), 'error', 'alert');
      })();
