  }, [showToast, t]);

  async function clearSavedGuardSession() {
    clearGuardToken();
    localStorage.removeItem('guard_id');
    await clearGuardAuth();
  }

  async function attemptQueueSync({
    reason = 'manual',
    announceReconnect = false,
    silentWhenEmpty = false,
    silentSummary = false,
  }: {
    reason?: string;
    announceReconnect?: boolean;
    silentWhenEmpty?: boolean;
    silentSummary?: boolean;
  } = {}) {
    const token = getGuardToken();
    if (!token) {
      await refreshPendingCount();
      return null;
    }

    if (!navigator.onLine) {
      if (!silentSummary) showToast(t('sync_retry_unavailable'), 'error', 'wifi-off');
      await refreshPendingCount();
      return null;
    }

    if (syncInProgress) return lastSyncSummary;
    const pendingBefore = await refreshPendingCount();
    if (pendingBefore === 0) {
      const summary = { reason, at: new Date().toISOString(), pendingBefore: 0, success: 0, failed: 0, review: 0 };
      setLastSyncSummary(summary);
      if (announceReconnect) showToast(t('back_online'), 'success', 'wifi');
      if (!silentWhenEmpty && !announceReconnect) showToast(t('sync_idle'), 'info', 'info');
      return summary;
    }

    setSyncInProgress(true);
    showToast(interpolate(t('sync_replay_started'), { count: pendingBefore }), 'info', 'refresh');
    try {
      const result = await processQueue(token);
      const summary = {
        reason,
        at: new Date().toISOString(),
        pendingBefore,
        success: result.success,
        failed: result.failed,
        review: result.review,
        results: result.results,
