              review: result.review,
              failed: result.failed,
            }),
          result.failed > 0 ? 'error' : result.review > 0 ? 'info' : 'success',
          result.failed > 0 ? 'alert' : result.review > 0 ? 'info' : 'check',
        );
      }
      return summary;
    } finally {
      setSyncInProgress(false);
    }
  }

  return (
    <>
      <div id="app-boot" aria-live="polite">
        <div className="app-boot-card">
          <div className="spinner" aria-hidden="true" />
          <div>{bootMessage}</div>
