              void attemptQueueSync({ reason: 'login', silentWhenEmpty: true, silentSummary: true });
            }}
          />
        ) : (
          <>
            {screen === 'scanner' ? (
              <ScannerScreen
                t={t}
                showToast={showToast}
                pendingCount={pendingCount}
                syncInProgress={syncInProgress}
                online={online}
                attemptQueueSync={attemptQueueSync}
                refreshPendingCount={refreshPendingCount}
              />
            ) : null}
            {screen === 'visitors' ? <VisitorsScreen t={t} showToast={showToast} online={online} refreshPendingCount={refreshPendingCount} /> : null}
            {screen === 'manual' ? <ManualScreen t={t} showToast={showToast} online={online} refreshPendingCount={refreshPendingCount} /> : null}
            {screen === 'expected' ? <ExpectedGuestsScreen t={t} showToast={showToast} online={online} /> : null}
            {screen === 'settings' ? (
              <SettingsScreen
                t={t}
                lang={lang}
                setLang={setLang}
                pendingCount={pendingCount}
                lastSyncSummary={lastSyncSummary}
                syncInProgress={syncInProgress}
                attemptQueueSync={attemptQueueSync}
                onLogout={async () => {
                  await guardLogout();
                  await clearSavedGuardSession();
                  setScreen('login');
                  await refreshPendingCount();
                }}
              />
            ) : null}
            {canInstallApp ? <InstallAppButton t={t} onInstall={handleInstallApp} /> : null}
            <BottomNav active={screen} setScreen={setScreen} t={t} pendingCount={pendingCount} />
          </>
        )}
        {screen === 'login' && canInstallApp ? <InstallAppButton t={t} onInstall={handleInstallApp} /> : null}
      </div>
    </>
  );
}

