      </div>
    </div>
  );
}

function ScannerScreen({
  t,
  showToast,
  pendingCount,
  syncInProgress,
  online,
  attemptQueueSync,
  refreshPendingCount,
}: {
  t: (key: string) => string;
  showToast: (message: string, tone?: ToastTone, icon?: IconName) => void;
  pendingCount: number;
  syncInProgress: boolean;
  online: boolean;
  attemptQueueSync: (options?: SyncOptions) => Promise<SyncSummary | null>;
  refreshPendingCount: () => Promise<number>;
}) {
  const [scannerActive, setScannerActive] = useState(true);
  const [restartKey, setRestartKey] = useState(0);
  const [loading, setLoading] = useState(false);
  const [currentCard, setCurrentCard] = useState<CurrentVisitorCard | null>(null);

  const startScanner = useCallback(() => {
    setCurrentCard(null);
    setLoading(false);
    setScannerActive(true);
    setRestartKey((value) => value + 1);
  }, []);

  async function handleScannedValue(value: string) {
    setScannerActive(false);
    const extracted = extractToken(value);
    if (!extracted.token) return;
    await handleQRResult(extracted);
  }

  async function handleQRResult(extracted: ExtractedQrToken) {
    setLoading(true);
    const res = await verifyQr(extracted.token);
    setLoading(false);

    if (res.offline) {
      const expectedMatch = findCachedExpectedGuestByToken(extracted.token);
      const visitorMeta = expectedMatch
        ? expectedGuestToMeta(expectedMatch)
        : extracted.visitorMeta;
      if (expectedMatch) showToast(t('expected_match_found'), 'info', 'search');
      setCurrentCard({ token: extracted.token, offlinePending: true, visitorMeta });
      return;
    }
    if (!res.data?.invitation) {
      setCurrentCard({ token: extracted.token, data: res.data });
      return;
    }
    const card = { token: extracted.token, data: res.data };
    setCurrentCard(card);
    if (
      res.ok &&
      res.data.valid &&
      res.data.invitation.approval_status === 'approved' &&
      !res.data.session
    ) {
      showToast(t('auto_checking_in'), 'info', 'check');
      await checkIn(card);
    }
  }

  async function checkIn(card: CurrentVisitorCard) {
    const res = await checkInVisitor(card.token);
    if (res.ok) {
      showToast(t('checked_in'), 'success', 'check');
      setCurrentCard({ ...card, data: { ...card.data!, session: res.data.session } });
      return;
    }
    if (res.offline) {
      const invitation = card.data?.invitation;
      const event = createOfflineEvent({
        eventType: 'qr_checkin_capture',
        ...getGuardContext(),
        qrToken: card.token,
        scannedRawValue: card.token,
        visitorName: invitation?.visitor_name || undefined,
        hostName: invitation?.host_employee_name || undefined,
        purpose: invitation?.purpose || undefined,
      }) as OfflineEventRecord;
      const recordId = await enqueue(event) as number;
      await refreshPendingCount();
      void registerBackgroundSync();
      setCurrentCard({ ...card, offlinePending: true, offlineEventId: event.offlineEventId });
      showToast(t('checkin_saved_offline'), 'info', 'offline');
      return;
    }
    showToast(res.data?.errorMessage ?? t('error'), 'error', 'alert');
  }

  async function saveOfflineQr(card: CurrentVisitorCard, form: OfflineQrFormValue) {
    const event = createOfflineEvent({
      eventType: 'qr_checkin_capture',
      ...getGuardContext(),
      qrToken: card.token,
      scannedRawValue: card.token,
      visitorName: form.visitorName || undefined,
      hostName: form.hostName || undefined,
      purpose: form.purpose || undefined,
      notes: form.notes || undefined,
    }) as OfflineEventRecord;
    const recordId = await enqueue(event) as number;
    await refreshPendingCount();
    void registerBackgroundSync();
    setCurrentCard({ ...card, offlinePending: true, offlineEventId: event.offlineEventId });
    showToast(t('checkin_saved_offline'), 'info', 'offline');
    return recordId;
  }

  return (
    <div id="scanner-screen" className="screen active" aria-label={t('aria_scanner')}>
      <Topbar title={t('page_scan')} icon="camera">
        <button className="icon-btn" type="button" title={t('aria_restart_camera')} aria-label={t('aria_restart_camera')} onClick={startScanner}>
          <IconGlyph name="refresh" />
        </button>
      </Topbar>
      <div className="scanner-body">
        <QrScanner active={scannerActive} restartKey={restartKey} onResult={handleScannedValue} />
        <div className="scan-hint">{t('scan_hint')}</div>
        {(syncInProgress || pendingCount > 0) ? (
          <ScannerSyncPanel
            t={t}
            pendingCount={pendingCount}
            syncInProgress={syncInProgress}
            online={online}
            attemptQueueSync={attemptQueueSync}
          />
        ) : null}
        {loading ? <div style={{ textAlign: 'center', padding: 24 }}><div className="spinner" style={{ margin: '0 auto' }} /></div> : null}
        {currentCard ? (
          <div id="visitor-card-section">
            <VisitorResultCard
              card={currentCard}
              t={t}
              onRetry={() => handleQRResult({ token: currentCard.token, visitorMeta: currentCard.visitorMeta ?? null })}
              onRescan={startScanner}

