function BottomNav({ active, setScreen, t, pendingCount }: { active: GuardScreen; setScreen: (screen: GuardScreen) => void; t: (key: string) => string; pendingCount: number }) {
  return (
    <nav className="bottom-nav" aria-label={t('aria_main_nav')}>
      {tabs.map((tab) => (
        <button key={tab.id} className={`nav-btn ${active === tab.id ? 'active' : ''}`} type="button" onClick={() => setScreen(tab.id)}>
          <span className="nav-icon" style={tab.id === 'scanner' ? { position: 'relative' } : undefined}>
            <IconGlyph name={tab.icon} />
            {tab.id === 'scanner' ? <span className="queue-badge" style={{ display: pendingCount > 0 ? 'flex' : 'none' }}>{pendingCount > 99 ? '99+' : pendingCount || ''}</span> : null}
          </span>
          <span>{t(tab.labelKey)}</span>
        </button>
      ))}
    </nav>
  );
