if (pathname === '/api/visitor/manual-entry' && method === 'POST') {
  const session = await guardAuth(req);
  if (!session) { json(res, 401, { error: 'Unauthorized' }); return true; }

  const body = await readBodyJson(req);
  const visitorName = String(body.visitor_name ?? '').trim();
  if (!visitorName) {
    json(res, 400, { error: 'visitor_name is required' });
    return true;
  }

  try {
    const hostId = normalizeBodyString(body.hostEmployeeId ?? body.host_employee_id);
    const hostById = hostId ? await getCoreStaffById(hostId) : null;
    const hostByContact = !hostById
      ? getStaffByContact({
        phone: normalizeBodyString(body.hostPhone ?? body.host_phone),
        email: normalizeBodyString(body.hostEmail ?? body.host_email),
      })
      : undefined;
    const hostStaff = hostById && hostById.isActive ? hostById : hostByContact;

    const invite = await createVisitorInvite({
      visitorName,
      visitorPhone: body.phone ? String(body.phone) : undefined,
