export async function notifyHostStakeholders(
  invitation: VisitorInvitation,
  sessionId: string,
  now: string,
  locationName?: string,
  includePrimaryHost = false,
): Promise<boolean> {
  const db = getOptionalPostgresDb();
  if (!db) return false;

  const stakeholders = await db
    .select()
    .from(visitorInvitationStakeholders)
    .where(eq(visitorInvitationStakeholders.invitationId, invitation.id));

  const notifyHosts = stakeholders.filter((stakeholder) => {
    if (stakeholder.role === 'primary_host' && !includePrimaryHost) return false;
    if (stakeholder.role !== 'cc_host' && stakeholder.role !== 'primary_host') return false;
    const notifyOn = Array.isArray(stakeholder.notifyOn) ? stakeholder.notifyOn : [];
    return notifyOn.includes('arrival');
  });
  if (notifyHosts.length === 0) return false;

  const lines = [
    `${invitation.visitor_name} has arrived.`,
    invitation.purpose ? `Purpose: ${invitation.purpose}` : null,
    invitation.host_employee_name ? `Primary host: ${invitation.host_employee_name}` : null,
    locationName ? `Location: ${locationName}` : null,
    `Arrived at: ${now}`,
  ].filter(Boolean) as string[];
  const text = lines.join('\n');
  let notified = false;

  for (const stakeholder of notifyHosts) {
    if (stakeholder.slackUserId) {
      try {
        const slackRef = await sendSlackDm({
          userId: stakeholder.slackUserId,
          text: `Visitor arrived: ${invitation.visitor_name}`,
          blocks: [{
            type: 'section',
            text: { type: 'mrkdwn', text },
          }],
        });
        notified = notified || !!slackRef?.ts;
      } catch (error) {
        console.error(`[HostNotifier] Failed to DM Slack CC host ${stakeholder.email ?? stakeholder.name}:`, error);
      }
    }

    if (stakeholder.email && isEmailConfigured()) {
      const result = await sendMail({
        to: stakeholder.email,
        subject: `Visitor arrived: ${invitation.visitor_name}`,
        text,
      });
      if (result.sent) {
        notified = true;
      } else if (result.error) {
        console.error(`[HostNotifier] Failed to email CC host ${stakeholder.email}:`, result.error);
      }
    }
  }

  if (notified) {
    await logAction({
      action: 'notification_sent',
      actorType: 'system',
      channel: 'stakeholder',
      sessionId,
      invitationId: invitation.id,
      metadata: { event: 'host_stakeholder_arrival', recipients: notifyHosts.map((item) => item.email ?? item.name).filter(Boolean) },
    });
  }

  return notified;
}

