async function notifySingleHost(
  staffMember: StaffRecord,
  invitation: VisitorInvitation,
  sessionId: string,
  now: string,
  locationName?: string,
  delayedSync?: boolean,
): Promise<boolean> {
  let notified = false;

  const telegramChannel = staffMember.channels?.find((c) => c.channel === 'telegram');
  const text = [
    `👋 Your visitor has arrived\\!`,
    ``,
    `👤 *${invitation.visitor_name}*`,
    invitation.purpose ? `📋 ${invitation.purpose}` : '',
    locationName ? `📍 ${locationName}` : '',
    `⏰ Arrived at ${now}`,
    delayedSync ? `_Delayed alert: synced after offline guard capture_` : '',
  ].filter(Boolean).join('\n');

  const buttons = [[
    { text: '🚶 Coming', callback_data: `host_response:${sessionId}:coming` },
    { text: '⏰ 5 min', callback_data: `host_response:${sessionId}:5min` },
    { text: '❌ Not expecting', callback_data: `host_response:${sessionId}:not_expecting` },
  ]];

  try {
    const hostChatId = Number(telegramChannel?.channelUid);
    if (Number.isFinite(hostChatId) && hostChatId !== 0) {
      await sendTelegramButtonDM(hostChatId, text, buttons);
      notified = true;
    }
  } catch (error) {
    console.error(`[HostNotifier] Failed to DM Telegram host ${staffMember.name}:`, error);
  }

  const slackChannel = staffMember.channels?.find((c) => c.channel === 'slack');
  if (slackChannel?.channelUid) {
    try {
      const slackBlocks = buildSlackHostResponseBlocks(
        invitation,
        sessionId,
        now,
        locationName,
        delayedSync,
        slackChannel.channelUid,
        invitation.id,
      );
      const slackRef = await sendSlackDm({
        userId: slackChannel.channelUid,
        text: `Visitor arrived: ${invitation.visitor_name}`,
        blocks: slackBlocks,
      });
      notified = notified || !!slackRef?.ts;
    } catch (error) {
      console.error(`[HostNotifier] Failed to DM Slack host ${staffMember.name}:`, error);
    }
  }

  return notified;
}

async function notifyResolvedSlackHost(
  host: ResolvedHostContact,
  invitation: VisitorInvitation,
  sessionId: string,
  now: string,
  locationName?: string,
  delayedSync?: boolean,
): Promise<boolean> {
  if (!host.slackUserId) return false;

  try {
    const slackBlocks = buildSlackHostResponseBlocks(
      invitation,
      sessionId,
      now,
      locationName,
      delayedSync,
      host.slackUserId,
      invitation.id,
    );
    const slackRef = await sendSlackDm({
      userId: host.slackUserId,
      text: `Visitor arrived: ${invitation.visitor_name}`,
      blocks: slackBlocks,
    });
    return Boolean(slackRef?.ts);
  } catch (error) {
    console.error(`[HostNotifier] Failed to DM Slack host ${host.email}:`, error);
    return false;
  }
}

