if (pathname === '/api/staff/search' && method === 'GET') {
  const session = await guardAuth(req);
  if (!session) { json(res, 401, { error: 'Unauthorized' }); return true; }

  const q = String(query.q ?? '').trim();
  const requestedLimit = Number(query.limit ?? (q ? 50 : 200));
  const limit = Number.isFinite(requestedLimit)
    ? Math.min(Math.max(requestedLimit, 1), 500)
    : (q ? 50 : 200);
  const matches = await queryStaffDirectory(q, limit);

  json(res, 200, {
    results: matches.map((s) => ({
      id: s.id,
      employeeCode: s.employeeCode ?? '',
      name: s.name,
      role: s.role,
      department: s.department ?? '',
      phone: s.phone ?? '',
      email: s.email ?? '',
      language: s.language ?? '',
      photoUrl: s.photoUrl ?? '',
      attendanceStatus: s.attendanceStatus,
      activeAttendanceId: s.activeAttendanceId ?? '',
      markedInAt: s.markedInAt ?? '',
      markedOutAt: s.markedOutAt ?? '',
    })),
  });
  return true;
}

if (pathname === '/api/staff/suggest' && method === 'GET') {
  const session = await guardAuth(req);
  if (!session) { json(res, 401, { error: 'Unauthorized' }); return true; }

  const q = String(query.q ?? '').trim();
  const requestedLimit = Number(query.limit ?? 12);
  const limit = Number.isFinite(requestedLimit)
    ? Math.min(Math.max(requestedLimit, 1), 25)
    : 12;

  json(res, 200, {
    results: searchCachedStaff(q, limit).map(mapStaffSuggestion),
  });
  return true;
}

if (pathname.startsWith('/api/staff/mark-in/') && method === 'POST') {
  const session = await guardAuth(req);
  if (!session) { json(res, 401, { error: 'Unauthorized' }); return true; }

