function HostSuggestInput({
  t,
  value,
  onChange,
  required,
}: {
  t: (key: string) => string;
  value: string;
  onChange: (value: string) => void;
  required?: boolean;
}) {
  const [suggestions, setSuggestions] = useState<StaffMember[]>([]);
  const [loading, setLoading] = useState(false);
  const [focused, setFocused] = useState(false);

  useEffect(() => {
    const query = value.trim();
    if (query.length < 2) {
      setSuggestions([]);
      setLoading(false);
      return;
    }
    let cancelled = false;
    const timer = window.setTimeout(async () => {
      setLoading(true);
      const res = await searchStaff(query);
      if (cancelled) return;
      setLoading(false);
      setSuggestions(res.ok ? (res.data.results ?? []).slice(0, 5) : []);
    }, 180);
    return () => {
      cancelled = true;
      window.clearTimeout(timer);
    };
  }, [value]);

