// In-memory + localStorage cache of the full staff directory, indexed for
// the client-side fuzzy matcher. Fetched once per session (or whenever the
// cache is older than STAFF_CACHE_TTL_MS). Keeps host autocomplete instant
// and offline-friendly — no per-keystroke network call.
const STAFF_CACHE_KEY = 'guard_staff_directory_v1';
const STAFF_CACHE_TTL_MS = 6 * 60 * 60 * 1000; // 6h
let staffIndexCache: { index: NameIndexEntry<StaffMember>[]; loadedAt: number } | null = null;
let staffIndexPromise: Promise<NameIndexEntry<StaffMember>[]> | null = null;

function readStaffCacheFromStorage(): { staff: StaffMember[]; loadedAt: number } | null {
  try {
    const raw = localStorage.getItem(STAFF_CACHE_KEY);
    if (!raw) return null;
    const parsed = JSON.parse(raw) as { staff: StaffMember[]; loadedAt: number };
    if (!Array.isArray(parsed.staff) || typeof parsed.loadedAt !== 'number') return null;
    return parsed;
  } catch {
    return null;
  }
}

async function loadStaffIndex(): Promise<NameIndexEntry<StaffMember>[]> {
  if (staffIndexCache && Date.now() - staffIndexCache.loadedAt < STAFF_CACHE_TTL_MS) {
    return staffIndexCache.index;
  }
  if (staffIndexPromise) return staffIndexPromise;

  staffIndexPromise = (async () => {
    // Serve stale cache from localStorage immediately so the first
    // keystroke after a refresh is still instant; refresh in background.
    const stored = readStaffCacheFromStorage();
    if (stored && !staffIndexCache) {
      staffIndexCache = { index: buildNameIndex(stored.staff, (s) => s.name), loadedAt: stored.loadedAt };
    }

    const res = await searchStaff('');
    if (res.ok) {
      const staff = res.data.results ?? [];
      staffIndexCache = { index: buildNameIndex(staff, (s) => s.name), loadedAt: Date.now() };
      try {
        localStorage.setItem(STAFF_CACHE_KEY, JSON.stringify({ staff, loadedAt: staffIndexCache.loadedAt }));
      } catch {
        // storage quota or private mode — ignore
      }
    }
    staffIndexPromise = null;
    return staffIndexCache?.index ?? [];
  })();

  return staffIndexPromise;
}

function HostSuggestInput({
  t,
  value,
  onChange,
  required,
}: {
  t: (key: string) => string;
  value: string;
  onChange: (value: string) => void;
  required?: boolean;
}) {
  const [index, setIndex] = useState<NameIndexEntry<StaffMember>[]>(() => staffIndexCache?.index ?? []);
  const [loading, setLoading] = useState(() => !staffIndexCache);
  const [focused, setFocused] = useState(false);

  useEffect(() => {
    let cancelled = false;
    void loadStaffIndex().then((next) => {
      if (cancelled) return;
      setIndex(next);
      setLoading(false);
    });
    return () => {
      cancelled = true;
    };
  }, []);

  const suggestions = useMemo(() => {
    const query = value.trim();
    if (query.length < 2 || index.length === 0) return [];
    return rankByName(index, query, 5).map((m) => m.item);
  }, [index, value]);

