export async function resolveAdminSession(req: IncomingMessage): Promise<AdminResolvedSession | null> {
  const token = getBearerToken(req);
  if (token) {
    const payload = parseToken(token);
    if (!payload) return null;

    if (payload.isSuperAdmin) {
      return {
        email: payload.email,
        name: payload.name,
        role: "super_admin",
        roleKeys: ["super_admin"],
